contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive the contract: provide amount to deposit and check balance increased correctly
    function run(address depositor, uint256 amount) public payable {
        // ensure this contract has enough ETH to forward
        require(msg.value == 0 ? address(this).balance >= amount : msg.value >= amount);

        // read previous balance via the public getter for balances (mapping has no getter in C),
        // so we observe it indirectly by having the depositor withdraw some known amount to set known state.
        // However balances is not public; instead we use the behavior of refund/withdraw to observe balance via transfer success.
        // Simpler: perform deposit from this contract and compare address(c).balance change vs amount.

        // Record contract balance before
        uint256 before = address(c).balance;

        // Call deposit forwarding ETH from this contract
        // If msg.value was provided to this call, forward that; else forward 'amount'
        uint256 send = msg.value == 0 ? amount : msg.value;
        c.deposit{value: send}();

        // Record contract balance after
        uint256 after = address(c).balance;

        // The general rule: the contract's balance must increase by exactly the sent amount (no silent loss via overflow)
        assert(after >= before + send);
    }

    // allow this test contract to receive ETH so it can forward deposits
    receive() external payable {}
}

