import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz depositor and amount; if deposit succeeds, the stored balance must equal previous + amount
    function testFuzz_property(address depositor, uint256 amount) public {
        vm.assume(depositor != address(0)); // keep depositor admissible
        // fund the depositor so they can send `amount` wei
        vm.deal(depositor, amount);

        // read balance before via the public mapping getter (balances is not public in original, but the test must use c's public surface)
        // The reference C has `mapping(address => uint256) balances;` (non-public). To observe balances we rely on the behaviour through deposit and contract balance.
        // We will observe the invariant using address(c).balance and the depositor's effective stored share by performing two deposits:
        // The reference ensures that a successful deposit increases the depositor's recorded share by exactly the amount sent.
        // To make this observable via public surface without a balances getter, we use a two-step differential test:
        // 1) have depositor deposit x
        // 2) then have depositor call refund() to withdraw their recorded balance
        // The refund() sends balances[depositor] to depositor and sets it to zero. Thus the amount received by depositor equals the stored balance.

        // First deposit
        vm.prank(depositor);
        bool ok1;
        try c.deposit{value: amount}() {
            ok1 = true;
        } catch {
            ok1 = false;
        }

        // If deposit reverted (shouldn't for reference for any admissible inputs), then we only assert nothing; but we must produce a universal property that holds when deposit succeeds.
        if (!ok1) {
            // If deposit reverted, the reference still satisfies that when deposit succeeds the equality holds; nothing to assert here.
            // To satisfy the single-assert rule we produce an assertion that relies on address(c).balance matching 0 when deposit failed and nothing else changed.
            assertTrue(address(c).balance == 0);
            return;
        }

        // Now call refund() from depositor to retrieve stored balance. refund sends balances[depositor] and zeroes it.
        // Record depositor balance before refund, then call refund, then measure difference to learn stored balance value.
        uint256 beforeRefund = depositor.balance;
        vm.prank(depositor);
        c.refund();
        uint256 afterRefund = depositor.balance;
        uint256 received = afterRefund - beforeRefund;

        // The general rule: when deposit succeeded, the stored balance that refund returns must equal the amount deposited.
        // Assert that the refunded amount equals the fuzzed deposit amount.
        assertTrue(received == amount);
    }
}

