        // bound amount to a reasonable range but allow zero too (rule still holds for zero)
        amount = bound(amount, 0, 1 ether);

        // Give the depositor some ETH to send
        vm.deal(depositor, amount + 1);

        // Record balance before deposit (via the contract's public mapping there's no getter, so
        // we must infer by calling deposit twice and observing change; instead we emulate a pre-existing balance
        // by having depositor call deposit once with some prior value if possible).

        // To make the property universally checkable via the contract's public surface we do two deposits:
        // First deposit some prior amount (prior), then deposit a second amount (amount). The property:
        // after the second deposit, recorded balance == prior + amount.
        // This will hold for the correct contract and fail for the mutant when prior > 0.

        uint256 prior = bound(uint256(uint160(depositor)) % (uint256(1 ether) + 1), 0, 1 ether);
        // Ensure depositor has enough funds for both prior and amount
        uint256 total = prior + amount;
        vm.deal(depositor, total + 1);

        // first deposit prior
        vm.prank(depositor);
        c.deposit{value: prior}();

        // record balance after first deposit by performing a second small deposit of 0 and reading contract balance
        // Note: mapping balances is not public, so we cannot directly read it. However the invariant we assert is about
        // the change caused by the second deposit: after second deposit, address(c).balance increases by amount and
        // the depositor's recorded share of that increase equals amount (i.e., total recorded for depositor == prior+amount).
        // We can observe the contract's total balance and use behavior of withdraw/refund to infer depositor's recorded balance.

        // To directly observe depositor's recorded balance we use the following approach:
        // We'll call refund() from depositor after the second deposit and check that the refunded amount equals prior + amount.
        // For correct contract, refund() sends balances[msg.sender] and zeros it. For mutant, when prior>0 the second deposit
        // overwrites balance and refund will send only amount (not prior+amount), violating the rule.

        // second deposit
        vm.prank(depositor);
        c.deposit{value: amount}();

        // Now call refund and capture gasless try/catch to ensure refund succeeded; refund transfers funds and sets balance to 0.
        // We observe address(c).balance before and after to learn refunded amount.
        uint256 before = address(c).balance;
        vm.prank(depositor);
        c.refund();
        uint256 after = address(c).balance;

        uint256 refunded = before - after;

        // The universal property: refunded == prior + amount (the depositor's recorded balance after two deposits)
        // This holds for the reference implementation for all prior and amount. The mutant (which zeroes old balance on second deposit)
        // will make refunded == amount when prior > 0, violating the equality for some inputs.
        assertTrue(refunded == prior + amount);
    }
}

